def check_l_ref(metrics_by_candidate: dict[str, list[EpisodeMetricSet]]) -> str:
    """Criterion 5: ``L_ref`` ≤ ``path_length_m`` on every success.

    A shortest path that is longer than the route actually driven means
    one of the two is wrong, and both feed ``path_efficiency``. Checked
    on successes only: a failed episode stopped early, so its path is
    legitimately shorter than any route to the goal.
    """
    checked = 0
    for candidate_id, rows in metrics_by_candidate.items():
        for row in rows:
            if not row.success:
                continue
            checked += 1
            if row.l_ref_m > row.path_length_m + 1e-9:
                raise SliceFailure(
                    f"candidate {candidate_id}, episode {row.episode_context_id}: "
                    f"L_ref {row.l_ref_m:.3f} m exceeds the driven path "
                    f"{row.path_length_m:.3f} m"
                )
    return f"L_ref ≤ path_length on all {checked} successful episodes"

