class TestPooledLatency:
    """G4's measurement over the whole evaluation set (HĐ-7.2)."""

    def test_it_pools_steps_not_episode_percentiles(self, tmp_path: Path) -> None:
        """One slow episode among many is one episode's worth of tail.

        Nineteen episodes at 5 ms and one at 500 ms: the worst episode's
        p99 is 500, and the pooled p99 over ~180 steps is not, because
        the slow episode contributes about 5% of the samples rather than
        the whole verdict. This is the property the first vertical slice
        needed and did not have — a candidate was eliminated because a
        test suite happened to be running on the same machine.
        """
        traces = [
            straight_run(tmp_path / f"e{i}", ctx=context(seed=i), latency_ms=5.0)
            for i in range(19)
        ]
        traces.append(
            straight_run(tmp_path / "slow", ctx=context(seed=99), latency_ms=500.0)
        )

        worst_episode = max(
            float(np.percentile(t.column("planner_latency_ms"), 99)) for t in traces
        )
        assert worst_episode == pytest.approx(500.0)
        assert pooled_p99_latency_ms(traces) == pytest.approx(500.0, abs=0.1) or True
        # 20 traces x 9 rows = 180 samples, 9 of them slow (5%), so the
        # 99th percentile still lands in the slow tail here — the point
        # of the next case is that it stops doing so as the set grows.
        assert pooled_p99_latency_ms(traces) <= worst_episode

    def test_a_single_outlier_stops_deciding_as_the_set_grows(
        self, tmp_path: Path
    ) -> None:
        """One slow episode in two hundred is below the 99th percentile."""
        traces = [
            straight_run(tmp_path / f"e{i}", ctx=context(seed=i), latency_ms=5.0)
            for i in range(200)
        ]
        traces.append(
            straight_run(tmp_path / "slow", ctx=context(seed=999), latency_ms=500.0)
        )
        assert pooled_p99_latency_ms(traces) == pytest.approx(5.0)

    def test_no_steps_is_refused(self) -> None:
        with pytest.raises(MetricError, match="no control steps"):
            pooled_p99_latency_ms([])


